<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($pageTitle ?? 'Users & Faculty') ?></title>
<style>
:root{--navy:#12385f;--blue:#1c5b96;--teal:#16877e;--ink:#1e3043;--muted:#64788c;--line:#dce6f1;--bg:#f1f6fb;--white:#fff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f4f8fc,#eaf2f9);font-family:Segoe UI,Arial,sans-serif;color:var(--ink)}.top{background:linear-gradient(115deg,#0b3768,#155a91 65%,#147e82);color:#fff;padding:22px clamp(16px,4vw,42px);display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;box-shadow:0 5px 18px #12375b20}.eyebrow{text-transform:uppercase;letter-spacing:1.5px;font-size:11px;font-weight:700;color:#c7e9f7}.top h1{margin:6px 0 4px;font-size:clamp(23px,3vw,30px)}.top p{margin:0;color:#e0edf8;font-size:13px}.actions{display:flex;gap:9px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border-radius:9px;padding:10px 14px;font-size:13px;font-weight:700;border:1px solid transparent;cursor:pointer}.btn-light{background:#fff;color:var(--navy)}.btn-primary{background:linear-gradient(110deg,#164b7b,#14877e);color:#fff}.btn-ghost{color:#fff;border-color:#ffffff75;background:#ffffff12}.wrap{max-width:1450px;margin:24px auto;padding:0 20px 35px}.alert{border-radius:10px;padding:12px 15px;margin-bottom:12px;font-size:13px}.alert-error{background:#fff0f0;border:1px solid #f0bcbc;color:#8e2a2a}.alert-ok{background:#e9f8f1;border:1px solid #b6e6d0;color:#176747}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:18px}.stat{background:#fff;border:1px solid var(--line);border-radius:14px;padding:17px 19px;box-shadow:0 5px 18px #15395e08;display:flex;justify-content:space-between;align-items:center}.stat-label{font-size:12px;color:var(--muted);font-weight:600}.stat-num{font-size:29px;color:var(--navy);font-weight:750;margin-top:3px}.stat-icon{width:44px;height:44px;border-radius:12px;background:#e7f1ff;color:#1c5b9c;display:grid;place-items:center}.stat-icon svg{width:23px;height:23px}.panel{background:#ffffffed;border:1px solid var(--line);border-radius:15px;margin:14px 0;padding:0 16px 16px;box-shadow:0 5px 20px #15395e09;overflow:hidden}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:17px 2px 13px;border-bottom:1px solid #e8eef5;margin-bottom:13px}.panel-head h2{font-size:18px;color:var(--navy);margin:0}.panel-head p{font-size:12px;color:var(--muted);margin:4px 0 0}.search{width:min(320px,100%);border:1px solid #cfdae7;border-radius:9px;padding:10px 12px;font-size:13px;outline:none}.search:focus{border-color:#4b8bc9;box-shadow:0 0 0 3px #4b8bc91c}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:900px;font-size:13px}th{text-align:left;text-transform:uppercase;letter-spacing:.45px;font-size:10px;color:#61788e;background:#f5f8fc;padding:12px 11px;border-bottom:1px solid var(--line)}td{padding:12px 11px;border-bottom:1px solid #e9eff5;vertical-align:middle}tbody tr.user-row{cursor:pointer}tbody tr.user-row:hover{background:#eef7ff}tbody tr.user-row:focus{outline:2px solid #4b8bc9;outline-offset:-2px}.id{font-variant-numeric:tabular-nums;color:#61778c}.name{font-weight:700;color:#203b57}.pill{display:inline-block;padding:5px 9px;border-radius:99px;background:#e3f6f2;color:#087b70;font-size:11px;font-weight:700;white-space:nowrap}.pill.role-0,.pill.role-1{background:#e8efff;color:#2855a2}.pill.role-3{background:#fff1d9;color:#895a08}.empty{padding:25px;text-align:center;color:var(--muted)}.bottom{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:#8192a4;font-size:11px;padding:12px 3px}.hint{font-size:12px;color:var(--muted)}@media(max-width:650px){.wrap{padding:0 10px 25px;margin-top:14px}.stats{gap:9px}.stat{padding:13px}.stat-num{font-size:24px}.panel{padding:0 10px 12px}.panel-head{align-items:flex-start}.search{width:100%}}
</style></head><body>
<header class="top"><div><div class="eyebrow">MCQ Bank · Administration</div><h1>Users &amp; Faculty</h1><p>Manage account identities and linked academic faculty records.</p></div><nav class="actions"><a class="btn btn-light" href="<?= site_url('dashboard/admin') ?>">← Dashboard</a><a class="btn btn-primary" href="<?= site_url('master/admin/users/new') ?>">＋ Add User</a><a class="btn btn-ghost" href="<?= site_url('logout') ?>">Logout</a></nav></header>
<main class="wrap">
<?php foreach (($errors ?? []) as $message): ?><div class="alert alert-error"><?= esc($message) ?></div><?php endforeach; ?>
<?php if ($msg = session()->getFlashdata('success')): ?><div class="alert alert-ok"><?= esc($msg) ?></div><?php endif; ?>
<?php if ($msg = session()->getFlashdata('error')): ?><div class="alert alert-error"><?= esc($msg) ?></div><?php endif; ?>
<div class="stats">
<div class="stat"><div><div class="stat-label">USER ACCOUNTS</div><div class="stat-num"><?= count($users ?? []) ?></div></div><div class="stat-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg></div></div>
<div class="stat"><div><div class="stat-label">FACULTY RECORDS</div><div class="stat-num"><?= count($faculty ?? []) ?></div></div><div class="stat-icon" style="background:#e4f7f0;color:#14795e" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m2 8 10-5 10 5-10 5L2 8Z"/><path d="M6 10v5c3.5 3 8.5 3 12 0v-5M22 8v6"/><path d="M10 21h4M12 18v3"/></svg></div></div></div>
<section class="panel"><div class="panel-head"><div><h2>User Accounts</h2><p>Manage account status here. Passwords are never displayed.</p></div><input class="search" type="search" placeholder="Search name, username, ID or role…" aria-label="Search user accounts" data-search="usersTable"></div>
<div class="table-wrap"><table id="usersTable"><thead><tr><th>User ID</th><th>Full Name</th><th>Username</th><th>Role</th><th>Status</th><th>Account Control</th></tr></thead><tbody>
<?php if (empty($users)): ?><tr><td colspan="6" class="empty">No user accounts found.</td></tr><?php else: foreach ($users as $u): $role=(string)($u['RollID']??''); $url=site_url('master/admin/users/edit/'.(int)$u['UserID']); ?><tr class="user-row" tabindex="0" data-href="<?= esc($url) ?>" aria-label="Edit account <?= esc($u['UserName']??'') ?>"><td class="id"><?= esc($u['UserID']??'') ?></td><td class="name"><?= esc(($u['FullName']??'') ?: '—') ?></td><td class="name"><?= esc($u['UserName']??'') ?></td><td><span class="pill role-<?= esc($role) ?>"><?= esc($roleLabels[$role]??('Role '.$role)) ?></span></td><td><?php $active=(int)($u['is_active']??1)===1; ?><span class="pill" style="background:<?= $active?'#e2f7eb':'#fff0f0' ?>;color:<?= $active?'#087443':'#b42323' ?>"><?= $active?'Active':'Inactive' ?></span></td><td><div style="display:flex;gap:7px;flex-wrap:wrap"><form method="post" action="<?= site_url('master/admin/users/toggle-status/'.(int)$u['UserID']) ?>" onsubmit="return confirm('<?= $active?'Deactivate':'Activate' ?> this account?')"><?= csrf_field() ?><button class="btn" type="submit" style="padding:7px 10px;border-color:<?= $active?'#ffc2c2':'#9dddbb' ?>;background:#fff;color:<?= $active?'#b42323':'#087443' ?>"><?= $active?'Deactivate':'Activate' ?></button></form></div></td></tr><?php endforeach; endif; ?>
</tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>Teaching Faculty Records</h2><p>Academic identity, department, subject and designation. Faculty accounts link by matching User ID and Faculty ID.</p></div><input class="search" type="search" placeholder="Search faculty, department or subject…" aria-label="Search faculty records" data-search="facultyTable"></div><div class="table-wrap"><table id="facultyTable"><thead><tr><th>Faculty ID</th><th>Faculty Name</th><th>Department</th><th>Subject</th><th>Designation</th></tr></thead><tbody>
<?php if (empty($faculty)): ?><tr><td colspan="5" class="empty">No faculty records found.</td></tr><?php else: foreach ($faculty as $p): ?><tr><td class="id"><?= esc($p['author_id']??'') ?></td><td class="name"><?= esc($p['author_name']??'') ?></td><td><?= esc($p['department_name']??'—') ?></td><td><?= esc($p['subject_name']??'—') ?></td><td><?= esc($p['designation_name']??'—') ?></td></tr><?php endforeach; endif; ?>
</tbody></table></div></section><div class="bottom"><span>MCQ Bank · Administration workspace</span><span>Account status controls · New faculty accounts create linked user and author records</span></div></main>
<script>
document.querySelectorAll('[data-search]').forEach(function(input){input.addEventListener('input',function(){var table=document.getElementById(input.dataset.search);if(!table)return;var q=input.value.toLocaleLowerCase();table.querySelectorAll('tbody tr').forEach(function(row){row.style.display=row.innerText.toLocaleLowerCase().includes(q)?'':'none';});});});
document.querySelectorAll('tr.user-row[data-href]').forEach(function(row){function openRecord(){window.location.href=row.dataset.href;}row.addEventListener('click',function(event){if(event.target.closest('a,button,input,select,textarea,label,form'))return;openRecord();});row.addEventListener('keydown',function(event){if((event.key==='Enter'||event.key===' ')&&event.target===row){event.preventDefault();openRecord();}});});
</script></body></html>
